export function initializeHistoricalV3(runtime) {
  const window = runtime.window;
  const document = runtime.document;
  const location = runtime.location;
  const CM3 = runtime.CM3;
  const addEventListener = runtime.addEventListener;
  const removeEventListener = runtime.removeEventListener;
  const innerWidth = runtime.window.innerWidth;
  const innerHeight = runtime.window.innerHeight;
  const devicePixelRatio = runtime.window.devicePixelRatio;
  const matchMedia = runtime.window.matchMedia.bind(runtime.window);
  const performance = runtime.window.performance;
  const requestAnimationFrame = runtime.window.requestAnimationFrame.bind(runtime.window);
  const cancelAnimationFrame = runtime.window.cancelAnimationFrame.bind(runtime.window);
  const setTimeout = runtime.window.setTimeout.bind(runtime.window);
  const clearTimeout = runtime.window.clearTimeout.bind(runtime.window);
  const localStorage = runtime.window.localStorage;
  const IntersectionObserver = runtime.window.IntersectionObserver;

  runtime.V3_COLL = {
    ilan: "review/ilan/items",
    yanki: "review/yanki/items",
    isaret: "review/isaret/items",
    registry: "decisions/registry/items",
    owners: "decisions/owners/items"
  };

  runtime.V3.store = {
    ilan: {},
    yanki: {},
    isaret: {},
    registry: {},
    owners: {}
  };

  runtime.V3.storeState = "pending";

  runtime.V3.desk = "ilan";

  runtime.V3.onlyOpen = false;

  runtime.V3.queue = {};
  // The "tahmini" tag stays until the notice review passes.

  runtime.V3_NOTE = {
    noSitemap: "noteNoSitemap",
    host: "noteHost",
    extraSitemap: "noteExtraSitemap",
    listing: "noteListing"
  };

  /* The measures are exposed for inspection. This is a research tool: anyone
     who wants to check a published number should be able to recompute it in the
     console against the same data the page used, rather than take it on trust. */
  window.CM = {
    data: runtime.D,
    actorMatrix: runtime.actorMatrix,
    actorsOf: runtime.actorsOf,
    valueProfile: runtime.valueProfile,
    valueHits: runtime.valueHits,
    VALUES: runtime.VALUES,
    yanatmaTest: runtime.yanatmaTest,
    deviationProfile: runtime.deviationProfile,
    timingProfile: runtime.timingProfile,
    registerCheck: runtime.registerCheck,
    blameStats: runtime.blameStats,
    findings: runtime.findings,
    runRules: runtime.runRules
  };

  try {
    var t = localStorage.getItem("yh-theme");
    document.documentElement.setAttribute("data-theme", t || "light");
  } catch (e) {
    document.documentElement.setAttribute("data-theme", "light");
  }

  addEventListener("hashchange", runtime.route);

  addEventListener("resize", function () {
    clearTimeout(window._lt);
    window._lt = setTimeout(runtime.layoutPills, 120);
  });

  runtime.route();
}
